const webhook = $('Prep Form Webhook').first().json.body || $('Prep Form Webhook').first().json || {};
const contact = webhook.contact || {};

const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : null;
};

const annualHouseholdIncome = num(webhook.annualHouseholdIncome);
const creditScore = num(webhook.creditScore);
const creditCardDebt = num(webhook.creditCardDebt);
const personalLoanDebt = num(webhook.personalLoanDebt);
const totalCreditLimit = num(webhook.totalCreditLimit);
const retirement401k = num(webhook.retirement401k);
const homeEquity = num(webhook.homeEquity);
const otherAssetsValue = num(webhook.otherAssetsValue);
const savings = num(webhook.savings);
const monthlyRentMortgage = num(webhook.monthlyRentMortgage);
const monthlyDebtPayments = num(webhook.monthlyDebtPayments);
const totalMonthlyExpenses = num(webhook.totalMonthlyExpenses);

const availableCredit = (totalCreditLimit !== null && creditCardDebt !== null)
  ? (totalCreditLimit - creditCardDebt) : null;
const utilization = (totalCreditLimit !== null && totalCreditLimit > 0 && creditCardDebt !== null)
  ? (creditCardDebt / totalCreditLimit) : null;
const pifPower = Math.max(0, availableCredit || 0) + Math.max(0, savings || 0);
const monthlyIncome = annualHouseholdIncome !== null ? (annualHouseholdIncome / 12) : null;
const monthlyCashflow = (monthlyIncome !== null && totalMonthlyExpenses !== null)
  ? (monthlyIncome - totalMonthlyExpenses) : null;

let route;
if (pifPower >= 15000) route = 'PIF (Pay In Full)';
else if (creditScore !== null && creditScore > 600 && utilization !== null && utilization <= 0.70) route = 'Payva Funding (likely accepted)';
else if (availableCredit !== null && availableCredit >= 6000) route = 'Split It';
else route = 'Payva Servicing';

const fmtMoney = (n) => (n === null || n === undefined) ? 'not provided' : ('$' + Math.round(Math.abs(n)).toLocaleString());
const fmtAvail = (n) => {
  if (n === null || n === undefined) return 'not provided';
  if (n < 0) return '-$' + Math.round(Math.abs(n)).toLocaleString() + ' (over limit)';
  return '$' + Math.round(n).toLocaleString();
};
const fmtPct = (n) => (n === null || n === undefined) ? 'n/a' : (Math.round(n * 100) + '%');
const fmtCashflow = (n) => {
  if (n === null || n === undefined) return 'not enough info';
  const s = n < 0 ? '-' : '+';
  return s + '$' + Math.round(Math.abs(n)).toLocaleString();
};
const fmtText = (v) => (!v || !String(v).trim()) ? 'not provided' : String(v).trim();
const fullName = fmtText(contact.fullName);
const email = fmtText(contact.email);
const stateStr = fmtText(webhook.state);
const debtNotes = (webhook.debtNotes && String(webhook.debtNotes).trim()) ? String(webhook.debtNotes).trim() : '';
const questions = (webhook.questions && String(webhook.questions).trim()) ? String(webhook.questions).trim() : '';
const otherAssetsNote = (webhook.otherAssetsNote && String(webhook.otherAssetsNote).trim()) ? String(webhook.otherAssetsNote).trim() : '';

// --- You & money (mindset) fields; absent on pre-v2 form submissions ---
const bankCheckFrequency = (webhook.bankCheckFrequency && String(webhook.bankCheckFrequency).trim()) ? String(webhook.bankCheckFrequency).trim() : '';
const financialLiteracy = num(webhook.financialLiteracy);
const moneyRelationshipWord = (webhook.moneyRelationshipWord && String(webhook.moneyRelationshipWord).trim()) ? String(webhook.moneyRelationshipWord).trim() : '';
const financialFrustration = (webhook.financialFrustration && String(webhook.financialFrustration).trim()) ? String(webhook.financialFrustration).trim() : '';
const hasMindset = !!(bankCheckFrequency || financialLiteracy !== null || moneyRelationshipWord || financialFrustration);


// --- Pre-fill check (2026-10-20): the form pre-fills the setter's numbers from a signed
// link token; show the closer what the prospect changed. No token at all = no block.
const PREFILL_LABELS = {
  annualHouseholdIncome: 'Income', creditScore: 'Credit score', creditCardDebt: 'Credit card debt',
  personalLoanDebt: 'Personal loan debt', retirement401k: '401k / retirement', homeEquity: 'Home equity',
  savings: 'Savings', state: 'State',
};
const prefill = (webhook.prefill && typeof webhook.prefill === 'object') ? webhook.prefill : null;
const prefillLines = [];
if (prefill && prefill.status === 'filled' && prefill.values && typeof prefill.values === 'object') {
  const fmtField = (k, v) => {
    if (v === null || v === undefined || v === '') return 'blank';
    if (k === 'state') return String(v);
    if (k === 'creditScore') return String(Math.round(Number(v)));
    return fmtMoney(Number(v));
  };
  const changes = [];
  let same = 0;
  for (const k of Object.keys(PREFILL_LABELS)) {
    if (!(k in prefill.values)) continue;
    const before = prefill.values[k];
    const after = webhook[k];
    const equal = k === 'state'
      ? String(before || '').trim() === String(after || '').trim()
      : (num(after) !== null && Math.abs(num(after) - Number(before)) < 0.5);
    if (equal) same++;
    else changes.push(PREFILL_LABELS[k] + ': ' + fmtField(k, before) + ' -> ' + fmtField(k, after));
  }
  const who = prefill.setter ? (prefill.setter + "'s call") : 'the setter call';
  if (changes.length) {
    prefillLines.push('Changed since ' + who + ' (setter -> prospect):');
    changes.forEach((c) => prefillLines.push('- ' + c));
    if (same) prefillLines.push(same + ' other pre-filled number' + (same === 1 ? '' : 's') + ' confirmed.');
  } else {
    prefillLines.push('Confirmed the numbers from ' + who + ', no changes (' + same + ' pre-filled).');
  }
} else if (prefill && prefill.reason && prefill.reason !== 'no_token') {
  prefillLines.push('Pre-fill: none (' + String(prefill.reason).slice(0, 40) + ')');
}

const lines = [];
lines.push('=== RECOMMENDED ROUTE ===');
lines.push(route);
lines.push('Program: $6,000');
lines.push('');
lines.push('=== Contact ===');
lines.push('Full name: ' + fullName);
lines.push('Email: ' + email);
lines.push('State: ' + stateStr);
lines.push('');
if (prefillLines.length) {
  lines.push('=== Setter Numbers Check ===');
  prefillLines.forEach((l) => lines.push(l));
  lines.push('');
}
if (hasMindset) {
  lines.push('=== You & Money ===');
  lines.push('Checks bank balance: ' + (bankCheckFrequency || 'not provided'));
  lines.push('Financial literacy (self-rated): ' + (financialLiteracy !== null ? (financialLiteracy + '/10') : 'not provided'));
  lines.push('Relationship with money: ' + (moneyRelationshipWord ? ('"' + moneyRelationshipWord + '"') : 'not provided'));
  if (financialFrustration) lines.push('Biggest frustration: ' + financialFrustration);
  lines.push('');
}
lines.push('=== Income & Cashflow ===');
lines.push('Gross annual income (before tax): ' + fmtMoney(annualHouseholdIncome));
lines.push('~ ' + fmtMoney(monthlyIncome) + ' /mo before tax');
lines.push('Total monthly expenses: ' + fmtMoney(totalMonthlyExpenses));
lines.push('Projected monthly cashflow: ' + fmtCashflow(monthlyCashflow) + ' /mo (approx, before tax)');
lines.push('');
lines.push('=== Credit ===');
lines.push('Credit score: ' + (creditScore !== null ? String(creditScore) : 'not provided'));
lines.push('Credit card debt: ' + fmtMoney(creditCardDebt));
lines.push('Personal loan debt: ' + fmtMoney(personalLoanDebt));
lines.push('Total credit limit: ' + fmtMoney(totalCreditLimit));
lines.push('Available credit: ' + fmtAvail(availableCredit));
lines.push('Utilization: ' + fmtPct(utilization));
lines.push('');
lines.push('=== Assets ===');
lines.push('401k / retirement: ' + fmtMoney(retirement401k));
lines.push('Home equity: ' + fmtMoney(homeEquity));
lines.push('Other assets: ' + fmtMoney(otherAssetsValue) + (otherAssetsNote ? ' (' + otherAssetsNote + ')' : ''));
lines.push('Savings: ' + fmtMoney(savings));
lines.push('');
lines.push('=== PIF Power ===');
lines.push('$' + Math.round(pifPower).toLocaleString() + ' (max(0, available credit) + max(0, savings))');
lines.push('');
lines.push('=== Monthly Money ===');
lines.push('Rent / mortgage: ' + fmtMoney(monthlyRentMortgage));
lines.push('Debt payments: ' + fmtMoney(monthlyDebtPayments));
lines.push('Total expenses: ' + fmtMoney(totalMonthlyExpenses));
lines.push('');
lines.push('=== Free text ===');
lines.push('Debt notes: ' + (debtNotes || '(none)'));
lines.push('Questions: ' + (questions || '(none)'));

const noteBody = lines.join('\n');
const contactId = $('Resolve Contact').first().json.contacts[0].id;
return [{ json: { contactId, noteBody, route } }];

