const closerStr = String(closerRaw || '').toLowerCase().trim();
const closerFirst = closerStr.split(/\s+/)[0] || '';
// Try full-name match first, then first-name match.
let slackId = nameToSlack[closerStr] || nameToSlack[closerFirst];
