let apptNote = '';
if (!slackId) {
  let events = [];
  try { const r = $('Get Closer Appts').first().json || {}; events = Array.isArray(r.events) ? r.events : []; } catch (e) { events = []; }
  const now = Date.now();
  const isCloserAppt = (a) => /finance strategy session|follow-up call|closer/i.test(a.title || '')
    && ['confirmed', 'showed', 'new'].includes(String(a.appointmentStatus || '').toLowerCase())
    && !!ghlUserToSlack[a.assignedUserId];
  const closerAppts = events.filter(isCloserAppt);
  const t = (a) => new Date(a.startTime).getTime();
  const upcoming = closerAppts.filter(a => t(a) >= now - 6 * 3600 * 1000).sort((a, b) => t(a) - t(b));
  const past = closerAppts.filter(a => t(a) < now - 6 * 3600 * 1000).sort((a, b) => t(b) - t(a));
  const pick = upcoming[0] || past[0];
  if (pick) {
    slackId = ghlUserToSlack[pick.assignedUserId];
    apptNote = ' (from GHL appointment ' + String(pick.startTime).slice(0, 10) + ')';
  }
}
const closerMention = slackId
  ? ('<@' + slackId + '>' + apptNote)
  : (closerRaw ? String(closerRaw) : 'unresolved, <@U09JJ9DL40L> to sort');

// Was the GHL contact found?
const searchResp = $('Resolve Contact').first().json || {};
const found = Array.isArray(searchResp.contacts) && searchResp.contacts.length > 0;

